/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-stepper {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  font-weight: var(--ui-type-body-weight);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-stepper {
  --ui-stepper-height: var(--ui-control-height-md, 40px);
  --ui-stepper-marker-size: max(
    calc(var(--ui-control-height-md, 40px) - var(--ui-space, 4px) * 3),
    calc(var(--ui-type-label-size) * var(--ui-type-label-line-height) + var(--ui-border-width) * 2)
  );
}
:where([data-moru-registry]) .ui-stepper-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ui-control-gap);
  padding: 0;
  margin: 0;
  list-style: none;
}
:where([data-moru-registry]) .ui-stepper-item {
  flex: 1 1 110px;
  min-width: 0;
  position: relative;
}
:where([data-moru-registry]) .ui-stepper-button {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  min-height: var(--ui-stepper-height);
  align-items: center;
  gap: var(--ui-control-gap);
  border: var(--ui-border-width) solid transparent;
  border-radius: var(--ui-radius);
  background: transparent;
  padding: calc(var(--ui-space) * 2);
  text-align: start;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: background var(--ui-duration);
}
:where([data-moru-registry]) .ui-stepper-button:not(:disabled):hover {
  background: var(--ui-surface-hover);
}
:where([data-moru-registry]) .ui-stepper-button:focus-visible {
  outline: 2px solid var(--ui-focus-ring);
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-stepper-button:disabled {
  cursor: default;
}
:where([data-moru-registry]) .ui-stepper-item[data-status='pending'] .ui-stepper-button:disabled {
  color: var(--ui-muted);
}
:where([data-moru-registry]) .ui-stepper[data-disabled] .ui-stepper-button {
  opacity: 0.55;
}
:where([data-moru-registry]) .ui-stepper-marker {
  box-sizing: border-box;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: var(--ui-stepper-marker-size);
  height: var(--ui-stepper-marker-size);
  border: var(--ui-border-width) solid var(--ui-control-hover-border);
  border-radius: 50%;
  color: var(--ui-muted);
  background: var(--ui-surface);
  font-size: var(--ui-type-label-size);
  line-height: 1;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
:where([data-moru-registry]) .ui-stepper-item[data-status='current'] .ui-stepper-marker {
  background: var(--ui-primary);
  border-color: var(--ui-primary);
  color: var(--ui-primary-foreground);
}
:where([data-moru-registry]) .ui-stepper-item[data-status='complete'] .ui-stepper-marker {
  background: var(--ui-primary-soft);
  border-color: var(--ui-primary-soft);
  color: var(--ui-primary-soft-text);
}
:where([data-moru-registry]) .ui-stepper-item[data-status='error'] .ui-stepper-marker {
  background: var(--ui-danger-soft);
  color: var(--ui-danger-text);
  border-color: var(--ui-danger-border);
}
:where([data-moru-registry]) .ui-stepper-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: calc(var(--ui-space) * 0.5);
}
:where([data-moru-registry]) .ui-stepper-label {
  font-size: var(--ui-type-label-size);
  line-height: var(--ui-type-label-line-height);
  font-weight: var(--ui-type-label-weight);
  letter-spacing: var(--ui-type-label-letter-spacing);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-stepper-description,
:where([data-moru-registry]) .ui-stepper-empty {
  color: var(--ui-muted);
  font-size: var(--ui-type-caption-size);
  line-height: var(--ui-type-caption-line-height);
  letter-spacing: var(--ui-type-caption-letter-spacing);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-stepper-panel,
:where([data-moru-registry]) .ui-stepper-completed {
  padding-block-start: var(--ui-form-gap);
}
:where([data-moru-registry]) .ui-stepper-panel[hidden] {
  display: none;
}
:where([data-moru-registry]) .ui-stepper[data-orientation='vertical'] .ui-stepper-list {
  flex-direction: column;
}
:where([data-moru-registry]) .ui-stepper[data-orientation='vertical'] .ui-stepper-item {
  flex-basis: auto;
}
:where([data-moru-registry]) .ui-stepper[data-orientation='vertical'] .ui-stepper-button {
  align-items: flex-start;
}
:where([data-moru-registry]) .ui-stepper[data-orientation='vertical'] .ui-stepper-item:not(:last-child)::after {
  content: '';
  position: absolute;
  inset-inline-start: calc(
    var(--ui-space) * 2 + var(--ui-border-width) + var(--ui-stepper-marker-size) / 2
  );
  top: calc(var(--ui-space) * 2 + var(--ui-border-width) + var(--ui-stepper-marker-size));
  bottom: calc(var(--ui-control-gap) * -1);
  border-inline-start: var(--ui-border-width) solid var(--ui-border);
  pointer-events: none;
}
:where([data-moru-registry]) .ui-stepper[data-size='sm'] {
  --ui-stepper-height: var(--ui-control-height-sm, 32px);
  --ui-stepper-marker-size: max(
    calc(var(--ui-control-height-sm, 32px) - var(--ui-space, 4px) * 2),
    calc(var(--ui-type-label-size) * var(--ui-type-label-line-height) + var(--ui-border-width) * 2)
  );
}
:where([data-moru-registry]) .ui-stepper[data-size='lg'] {
  --ui-stepper-height: var(--ui-control-height-lg, 48px);
  --ui-stepper-marker-size: max(
    calc(var(--ui-control-height-lg, 48px) - var(--ui-space, 4px) * 4),
    calc(var(--ui-type-label-size) * var(--ui-type-label-line-height) + var(--ui-border-width) * 2)
  );
}
@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-stepper-button {
    min-height: max(44px, var(--ui-stepper-height));
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-stepper-button {
    transition: none;
  }
}
@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-stepper-marker {
    border-color: ButtonText;
  }
  :where([data-moru-registry]) .ui-stepper-item[data-status='current'] .ui-stepper-marker {
    border-width: 3px;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useId, useState, type HTMLAttributes, type ReactNode } from 'react'
import { Check, X } from 'lucide-react'
import { cn } from './_lib/cn'
import './workflow-shared.css'
import './stepper.css'

export interface StepperItem {
  id: string
  label: string
  description?: string
  content?: ReactNode
  disabled?: boolean
  error?: boolean
}

export interface StepperProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'defaultValue' | 'onChange'
> {
  items: readonly StepperItem[]
  /** Zero-based index. items.length represents the completed sequence. */
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  /** Future steps stay unavailable until the host form validates and advances. */
  allowNextStepsSelect?: boolean
  allowStepSelect?: boolean
  disabled?: boolean
  orientation?: 'horizontal' | 'vertical'
  size?: 'sm' | 'md' | 'lg'
  completedContent?: ReactNode
}

export function normalizeStepperValue(value: number, count: number) {
  return Number.isFinite(value) ? Math.min(count, Math.max(0, Math.floor(value))) : 0
}

export function canSelectStep(
  index: number,
  active: number,
  count: number,
  options: {
    disabled?: boolean
    itemDisabled?: boolean
    allowStepSelect?: boolean
    allowNextStepsSelect?: boolean
  } = {},
) {
  return (
    Number.isInteger(index) &&
    index >= 0 &&
    index < count &&
    !options.disabled &&
    !options.itemDisabled &&
    options.allowStepSelect !== false &&
    (options.allowNextStepsSelect === true || index <= active)
  )
}

/** A form sequence uses an ordered list and native buttons, rather than tab semantics. */
export function Stepper({
  items,
  value,
  defaultValue = 0,
  onValueChange,
  allowNextStepsSelect = false,
  allowStepSelect = true,
  disabled,
  orientation = 'horizontal',
  size = 'md',
  completedContent,
  className,
  'aria-label': labelProp,
  ...props
}: StepperProps) {
  const { t } = useI18n()
  const label = labelProp ?? t('진행 단계')

  const [localValue, setLocalValue] = useState(defaultValue)
  const active = normalizeStepperValue(value ?? localValue, items.length)
  const id = useId()
  const completed = items.length > 0 && active === items.length
  function select(index: number) {
    if (
      !canSelectStep(index, active, items.length, {
        disabled,
        itemDisabled: items[index]?.disabled,
        allowStepSelect,
        allowNextStepsSelect,
      })
    )
      return
    if (value === undefined) setLocalValue(index)
    if (index !== active) onValueChange?.(index)
  }
  return (
    <div
      {...props}
      className={cn('ui-stepper', className)}
      data-orientation={orientation}
      data-size={size}
      data-disabled={disabled || undefined}
    >
      {items.length ? (
        <ol className="ui-stepper-list" aria-label={label}>
          {items.map((item, index) => {
            const status = item.error
              ? 'error'
              : index < active
                ? 'complete'
                : index === active
                  ? 'current'
                  : 'pending'
            const selectable = canSelectStep(index, active, items.length, {
              disabled,
              itemDisabled: item.disabled,
              allowStepSelect,
              allowNextStepsSelect,
            })
            const statusLabel = item.error
              ? t('오류 · 확인 필요')
              : index < active
                ? t('완료')
                : index === active
                  ? t('현재 단계')
                  : t('대기')
            return (
              <li key={item.id} className="ui-stepper-item" data-status={status}>
                <button
                  type="button"
                  id={`${id}-step-${index}`}
                  className="ui-stepper-button"
                  aria-current={index === active ? 'step' : undefined}
                  aria-controls={item.content != null ? `${id}-panel-${index}` : undefined}
                  disabled={!selectable}
                  onClick={() => select(index)}
                >
                  <span className="ui-stepper-marker" aria-hidden="true">
                    {item.error ? (
                      <X size={15} />
                    ) : index < active ? (
                      <Check size={15} />
                    ) : (
                      index + 1
                    )}
                  </span>
                  <span className="ui-stepper-copy">
                    <span className="ui-stepper-label">{item.label}</span>
                    {item.description && (
                      <span className="ui-stepper-description">{item.description}</span>
                    )}
                    <span className="ui-workflow-sr-only">{statusLabel}</span>
                  </span>
                </button>
              </li>
            )
          })}
        </ol>
      ) : (
        <p className="ui-stepper-empty">{t('등록된 단계가 없어요.')}</p>
      )}
      {items.map(
        (item, index) =>
          item.content != null && (
            <div
              key={item.id}
              id={`${id}-panel-${index}`}
              role="region"
              aria-labelledby={`${id}-step-${index}`}
              className="ui-stepper-panel"
              hidden={active !== index}
            >
              {item.content}
            </div>
          ),
      )}
      {completed && (
        <div className="ui-stepper-completed" role="status">
          {completedContent ?? t('모든 단계를 완료했어요.')}
        </div>
      )}
    </div>
  )
}
